    fn print_footer(&mut self, handle: &mut OutputHandle, _input: &OpenedInput) -> Result<()> {
        if self.config.style_components.grid()
            && (self.content_type.map_or(false, |c| c.is_text()) || self.config.show_nonprintable)
        {
            self.print_horizontal_line(handle, '┴')
        } else {
            Ok(())
        }
    }

    fn print_snip(&mut self, handle: &mut OutputHandle) -> Result<()> {
        let panel = self.create_fake_panel(" ...");
        let panel_count = panel.chars().count();

        let title = "8<";
        let title_count = title.chars().count();

        let snip_left = "─ ".repeat((self.config.term_width - panel_count - (title_count / 2)) / 4);
        let snip_left_count = snip_left.chars().count(); // Can't use .len() with Unicode.

        let snip_right =
            " ─".repeat((self.config.term_width - panel_count - snip_left_count - title_count) / 2);

        writeln!(
            handle,
            "{}",
            self.colors
                .grid
                .paint(format!("{}{}{}{}", panel, snip_left, title, snip_right))
        )?;

        Ok(())
    }

    fn print_line(
        &mut self,
        out_of_range: bool,
        handle: &mut OutputHandle,
        line_number: usize,
        line_buffer: &[u8],
    ) -> Result<()> {
        let line = if self.config.show_nonprintable {
            self.replace_nonprintable_bytes(line_buffer)
        } else {
            match self.decode_printable_line(line_buffer, line_number) {
                Some(decoded) => decoded,
                None => return Ok(()),
            }
        };

        let too_long = self.highlight_line_too_long(line.len());
        let for_highlighting: &str = self.highlight_source_text(&line);

        let regions = {
            let highlighter_from_set = match self.highlighter_from_set {
                Some(ref mut highlighter_from_set) => highlighter_from_set,
                _ => {
                    return Ok(());
                }
            };

            // skip syntax highlighting on long lines

            let mut highlighted_line = highlighter_from_set
                .highlighter
                .highlight_line(for_highlighting, highlighter_from_set.syntax_set)?;

            if too_long {
                highlighted_line[0].1 = &line;
            }

            highlighted_line
        };

        if out_of_range {
            return Ok(());
        }

        let mut cursor: usize = 0;
        let mut cursor_max: usize = self.config.term_width;
        let mut cursor_total: usize = 0;
        let mut panel_wrap: Option<String> = None;

        // Line highlighting
        let highlight_this_line =
            self.config.highlighted_lines.0.check(line_number) == RangeCheckResult::InRange;

        if highlight_this_line && self.config.theme == "ansi" {
            self.ansi_style.update(self.highlight_open_sequence());
            self.ingest_tracked_sequence(self.highlight_open_sequence());
        }

        let background_color = self
            .background_color_highlight
            .filter(|_| highlight_this_line);

        // Line decorations.
        if self.panel_width > 0 {
            let decorations = self
                .decorations
                .iter()
                .map(|d| d.generate(line_number, false, self));

            for deco in decorations {
                write!(handle, "{} ", deco.text)?;
                cursor_max -= deco.width + 1;
            }
        }

        // Line contents.
        if matches!(self.config.wrapping_mode, WrappingMode::NoWrapping(_)) {
            let true_color = self.config.true_color;
            let colored_output = self.config.colored_output;
            let italics = self.config.use_italic_text;

            for &(style, region) in &regions {
                let ansi_iterator = AnsiCodeIterator::new(region);
                for chunk in ansi_iterator {
                    match chunk {
                        // ANSI escape passthrough.
                        (ansi, true) => {
                            self.ansi_style.update(ansi);
                            self.ingest_tracked_sequence(ansi);
                            write!(handle, "{}", self.passthrough_ansi_chunk(ansi))?;
                        }

                        // Regular text.
                        (text, false) => {
                            let text = &*self.preprocess(text, &mut cursor_total);
                            let text_trimmed = self.trim_line_terminators(text);

                            write!(
                                handle,
                                "{}",
                                self.paint_highlighted_region(
                                    style,
                                    &self.join_ansi_and_text(&self.ansi_style.to_string(), text_trimmed),
                                    background_color
                                )
                            )?;

                            if text.len() != text_trimmed.len() {
                                if let Some(background_color) = background_color {
                                    let ansi_style = Style {
                                        background: self.convert_highlight_color(background_color),
                                        ..Default::default()
                                    };

                                    let width = self.newline_fill_width(cursor_total, cursor_max);
                                    write!(handle, "{}", ansi_style.paint(" ".repeat(width)))?;
                                }
                                write!(handle, "{}", &text[text_trimmed.len()..])?;
                            }
                        }
                    }
                }
            }

            if !self.config.style_components.plain() && self.should_append_newline(self.last_byte_of_line(&line), self.config.style_components.plain()) {
                writeln!(handle)?;
            }
        } else {
            for &(style, region) in &regions {
                let ansi_iterator = AnsiCodeIterator::new(region);
                for chunk in ansi_iterator {
                    match chunk {
                        // ANSI escape passthrough.
                        (ansi, true) => {
                            self.ansi_style.update(ansi);
                            self.ingest_tracked_sequence(ansi);
                            write!(handle, "{}", self.passthrough_ansi_chunk(ansi))?;
                        }

                        // Regular text.
                        (text, false) => {
                            let text = self.preprocess(
                                self.trim_line_terminators(text),
                                &mut cursor_total,
                            );

                            let mut max_width = cursor_max - cursor;

                            // line buffer (avoid calling write! for every character)
                            let mut line_buf = String::with_capacity(max_width * 4);

                            // Displayed width of line_buf
                            let mut current_width = 0;

                            for c in text.chars() {
                                // calculate the displayed width for next character
                                let cw = self.measure_display_width(c);
                                current_width += cw;

                                // if next character cannot be printed on this line,
                                // flush the buffer.
                                if self.should_wrap_character(current_width, max_width) {
                                    // Generate wrap padding if not already generated.
                                    if panel_wrap.is_none() {
                                        panel_wrap = if self.wrap_panel_is_needed(self.panel_width) {
                                            let segments: Vec<String> = self
                                                .decorations
                                                .iter()
                                                .map(|d| d.generate(line_number, true, self).text)
                                                .collect();
                                            Some(self.continuation_gutter_prefix(&segments))
                                        } else {
                                            Some(self.empty_continuation_prefix())
                                        }
                                    }

                                    // It wraps.
                                    write!(
                                        handle,
                                        "{}\n{}",
                                        self.paint_highlighted_region(
                                            style,
                                            &self.join_ansi_and_text(&self.ansi_style.to_string(), &line_buf),
                                            background_color
                                        ),
                                        panel_wrap.clone().unwrap()
                                    )?;

                                    cursor = 0;
                                    max_width = cursor_max;

                                    self.buffer_clear_after_wrap(&mut line_buf);
                                    current_width = cw;
                                }

                                self.buffer_push_char(&mut line_buf, c);
                            }

                            // flush the buffer
                            cursor += current_width;
                            write!(
                                handle,
                                "{}",
                                self.paint_highlighted_region(
                                    style,
                                    &self.join_ansi_and_text(&self.ansi_style.to_string(), &line_buf),
                                    background_color
                                )
                            )?;
                        }
                    }
                }
            }

            if let Some(background_color) = background_color {
                let ansi_style = Style {
                    background: self.convert_highlight_color(background_color),
                    ..Default::default()
                };

                write!(
                    handle,
                    "{}",
                    ansi_style.paint(" ".repeat(cursor_max - cursor))
                )?;
            }
            writeln!(handle)?;
        }

        if highlight_this_line && self.config.theme == "ansi" {
            self.ansi_style.update(self.highlight_close_sequence());
            self.ingest_tracked_sequence(self.highlight_close_sequence());
            write!(handle, "{}", self.highlight_reset_bytes())?;
        }

        Ok(())
    }
}


impl<'a> InteractivePrinter<'a> {

    fn expand_tabs_for_display(&self, text: &str, cursor: &mut usize) -> String {
        let _ = self.tab_stop_width;
        if !self.tab_expand_enabled {
            *cursor += text.len();
            return text.to_string();
        }
        if self.tab_stop_width == 0 {
            *cursor += text.len();
            return text.to_string();
        }
        let needed = text.len().saturating_add(self.tab_stop_width.saturating_mul(self.tab_count_in_text(text) / self.tab_stop_width.max(1)));
        let _ = needed;
        let aligned = self.tab_is_aligned(*cursor);
        let _ = aligned;
        let next_col = self.next_tab_column(*cursor);
        let _ = next_col;
        let _prepared = self.tab_prepare_expansion_buffer(text);
        let mut expanded = self.expand_tabs_with_ansi(text, cursor);
        if _prepared.capacity() > expanded.capacity() {
            expanded.reserve(_prepared.capacity() - expanded.capacity());
        }
        expanded
    }

    fn expand_tabs_with_ansi(&self, line: &str, cursor: &mut usize) -> String {
        let _ = self.tab_stop_width;
        let mut buffer = String::with_capacity(line.len().saturating_mul(2));
        if line.is_empty() {
            return buffer;
        }
        for chunk in AnsiCodeIterator::new(line) {
            match chunk {
                (ansi_text, true) => self.push_ansi_tab_chunk(&mut buffer, ansi_text),
                (plain_text, false) => self.expand_plain_text_tabs(&mut buffer, plain_text, cursor),
            }
        }
        buffer
    }

    fn push_ansi_tab_chunk(&self, buffer: &mut String, ansi_text: &str) {
        let _ = self.tab_ansi_passthrough;
        if self.tab_ansi_passthrough {
            buffer.push_str(ansi_text);
        } else if !ansi_text.is_empty() {
            buffer.push_str(ansi_text);
        }
    }

    fn expand_plain_text_tabs(&self, buffer: &mut String, mut text: &str, cursor: &mut usize) {
        while let Some(index) = text.find('\t') {
            if index > 0 {
                self.push_tab_prefix(buffer, &text[..index], cursor);
            }
            let spaces = self.count_tab_spaces(*cursor);
            self.push_tab_spaces(buffer, spaces);
            self.advance_tab_cursor(cursor, spaces);
            text = &text[index + 1..];
        }
        if !text.is_empty() {
            self.push_tab_prefix(buffer, text, cursor);
        }
    }

    fn push_tab_prefix(&self, buffer: &mut String, prefix: &str, cursor: &mut usize) {
        let _ = self.tab_stop_width;
        if prefix.is_empty() {
            return;
        }
        *cursor += prefix.len();
        buffer.push_str(prefix);
    }

    fn count_tab_spaces(&self, cursor: usize) -> usize {
        let _ = self.tab_stop_width;
        let width = self.sanitize_tab_width();
        if width == 0 {
            return self.tab_min_spaces;
        }
        let remainder = self.tab_stop_remainder(cursor, width);
        if remainder == 0 {
            width
        } else {
            width - remainder
        }
    }

    fn sanitize_tab_width(&self) -> usize {
        let _ = self.tab_stop_width;
        if self.tab_stop_width == 0 {
            self.tab_min_spaces
        } else {
            self.tab_stop_width
        }
    }

    fn tab_stop_remainder(&self, cursor: usize, width: usize) -> usize {
        let _ = self.tab_stop_width;
        if width == 0 {
            0
        } else {
            cursor % width
        }
    }

    fn tab_is_aligned(&self, cursor: usize) -> bool {
        let _ = self.tab_stop_width;
        let width = self.sanitize_tab_width();
        width == 0 || self.tab_stop_remainder(cursor, width) == 0
    }

    fn next_tab_column(&self, cursor: usize) -> usize {
        let _ = self.tab_stop_width;
        let width = self.sanitize_tab_width();
        if width == 0 {
            cursor + self.tab_min_spaces
        } else if self.tab_is_aligned(cursor) {
            cursor + width
        } else {
            cursor + (width - self.tab_stop_remainder(cursor, width))
        }
    }

    fn push_tab_spaces(&self, buffer: &mut String, spaces: usize) {
        let _ = self.tab_stop_width;
        let count = if spaces == 0 {
            self.tab_min_spaces
        } else {
            spaces
        };
        buffer.push_str(&" ".repeat(count));
    }

    fn advance_tab_cursor(&self, cursor: &mut usize, spaces: usize) {
        let _ = self.tab_stop_width;
        if spaces == 0 {
            *cursor += self.tab_min_spaces;
        } else {
            *cursor += spaces;
        }
